raw:
{
  "core_conclusion": "A 문의는 발급/열람 여부와 채널에 따라 수수료가 달라지므로 확인이 필요하고, B 문의는 신청 시 요청하면 효력 있는 사항만 기재하여 발급받을 수 있습니다.",
  "missing_facts": [
    {
      "fact": "A가 자동차등록원부를 발급받았는지 열람만 했는지, 그리고 인터넷/방문/무인발급기 중 어떤 채널을 이용했는지",
      "blocks_core_answer": true,
      "changes_answer": "발급(300원)인지 열람(100원)인지, 인터넷(무료)인지 방문/무인발급기(유료)인지에 따라 정확한 비용이 결정됩니다."
    }
  ],
  "can_answer_now": false,
  "question": "A 문의에 대해, 자동차등록원부를 '발급'받았는지 '열람'만 했는지, 그리고 인터넷/방문/무인발급기 중 어떤 방법으로 이용하셨는지 알려주세요. (B 문의는 효력 있는 사항만 기재하여 발급 가능하므로 별도 확인 사항이 없습니다.)"
}

{
  "core_conclusion": "A는 요구 기관이 명시한 서류(등본 또는 초본)를 정확히 제출해야 하며, B는 가족 전체가 포함된 서류가 필요하므로 제적초본이 아닌 제적등본을 발급받아야 합니다.",
  "missing_facts": [
    {
      "fact": "A가 제적 서류를 제출해야 하는 구체적인 기관이나 용도(예: 병무청, 법원, 학교 등)",
      "blocks_core_answer": true,
      "changes_answer": "근거 본문(병역법 시행규칙 등)에 따르면 용도에 따라 요구되는 서류가 '제적등본'으로 특정되는 경우가 있어, 제출처를 알지 못하면 '아무거나 내면 안 되는지'에 대한 정확한 답(등본 필수 여부)을 확정할 수 없습니다."
    }
  ],
  "can_answer_now": false,
  "question": "A님, 제적 서류를 제출해야 하는 구체적인 기관이나 용도(예: 병무청, 법원, 학교 등)가 어디인지 알려주시겠어요?"
}

{
  "core_conclusion": "A는 부가세 과세표준증명(과세사업자용)과 면세사업자 수입금액증명(면세사업자용)의 대상 사업자 유형과 증명 내용이 다름을 안내하고, B는 여권정보 공동이용 동의 여부에 따라 여권 지참 필요 여부를 판단하되, 동의 여부를 확인하기 위해 화면에 표시된 안내 문구 또는 오류 메시지가 필요합니다.",
  "missing_facts": [
    {
      "fact": "B가 여권정보 공동이용 동의 여부를 확인하기 위해 화면에서 본 구체적인 안내 문구 또는 오류 메시지",
      "blocks_core_answer": true,
      "changes_answer": "화면 안내에 따라 동의가 완료된 상태인지(여권 불필요), 미동의 상태인지(여권 필요), 또는 시스템 오류인지 판단이 달라짐"
    }
  ],
  "can_answer_now": false,
  "question": "B 문의와 관련하여, 여권정보 공동이용 동의 여부를 확인하기 위해 화면에 표시된 구체적인 안내 문구 또는 오류 메시지가 무엇인가요?"
}

{
  "core_conclusion": "A는 무인발급기 사용 시 본인만 가능하므로 자녀가 부모의 증명서를 발급받을 수 없고, B는 정당한 이해관계인 자격으로 가족관계증명서를 청구할 때 신청서, 이해관계 소명 자료, 신분증명서를 제출해야 합니다.",
  "missing_facts": [
    {
      "fact": "A가 '이 화면'이라고 지칭한 구체적인 발급 채널(무인발급기, 인터넷, 방문 등)",
      "blocks_core_answer": true,
      "changes_answer": "무인발급기는 본인만 가능하여 자녀가 부모의 증명서를 발급받을 수 없지만, 인터넷이나 방문 신청은 자녀(직계혈족)가 부모의 증명서를 발급받을 수 있어 결론이 완전히 달라짐."
    }
  ],
  "can_answer_now": false,
  "question": "A 문의에서 '이 화면'이라고 하신 부분이 무인발급기인지, 인터넷(대법원 전자가족관계등록시스템 등)인지, 아니면 주민센터 방문인지 구체적으로 알려주세요. (무인발급기는 본인만 가능하고, 인터넷/방문은 자녀가 부모의 증명서를 발급받을 수 있어 안내 내용이 다릅니다.)"
}

{
  "core_conclusion": "A의 경우 아버지가 해외 체류 60일이 되는 날이 속하는 달의 다음 달부터 지급이 정지되며, B의 경우 주소지 관할이 아닌 지자체에서 신청서를 접수하면 해당 서류는 관할 지자체로 지체 없이 이송됩니다.",
  "missing_facts": [
    {
      "fact": "아버지가 해외로 출국한 정확한 날짜(또는 60일이 되는 날)",
      "blocks_core_answer": true,
      "changes_answer": "출국일이 없으면 '60일이 되는 날'을 계산할 수 없어 정지 시작 월을 특정할 수 없습니다."
    }
  ],
  "can_answer_now": false,
  "question": "아버지가 해외로 출국하신 정확한 날짜(또는 출국일로부터 60일이 되는 날)를 알려주세요."
}

{
  "core_conclusion": "A는 등기부상 명의 확인 실패(주민번호 미기재 또는 불일치)로 인해 전자등기사항증명서 발급수수료 면제 대상에서 제외되어 수수료가 부과된 것이며, B는 초과 납부된 수수료는 원칙적으로 환급 대상이나, 환급 포기 시 등기신청서 여백에 포기 취지를 기재하고 기명날인 또는 서명을 해야 합니다.",
  "missing_facts": [
    {
      "fact": "A의 부동산 등기부상 소유권 등기명의인의 성명 및 주민등록번호(또는 부동산등기용등록번호)가 발급 신청인(본인)의 정보와 일치하는지 여부, 또는 등기부에 해당 정보가 기록되어 있는지 여부",
      "blocks_core_answer": true,
      "changes_answer": "면제 제외 사유(제15조의2 제1항 제1호 또는 제2호) 중 구체적으로 어느 항목에 해당하는지 확정하여 '뭐가 걸린 건지'를 정확히 짚어줄 수 없음"
    }
  ],
  "can_answer_now": false,
  "question": "A 문의에 대해, 인터넷등기소에서 본인 인증 시 '등기부상 명의 확인' 단계에서 실패한 경우, 등기부상 소유권 등기명의인의 성명 및 주민등록번호(또는 부동산등기용등록번호)가 신청인 본인의 정보와 일치하지 않았는지, 아니면 등기부에 해당 정보가 아예 기록되어 있지 않았는지 확인 가능한가요?"
}

{
  "core_conclusion": "A는 신청 시 행위제한 내용 제외 옵션을 체크했는지 확인이 필요하며, B는 토지이용계획확인서의 법정 처리기간은 '총 1일'로 등본(3시간)과 다릅니다.",
